ds = tabularTextDatastore('airlinesmall.csv', 'TreatAsMissing', 'NA', ...
    'SelectedVariableNames', {'ArrDelay'});
mapfun = @(data, info, kv) add(kv, 'delay', ...
    [sum(data.ArrDelay(~isnan(data.ArrDelay))), sum(~isnan(data.ArrDelay))]);
reducefun = @(key, iter, kv) reduceMean(key, iter, kv);
outds = mapreduce(ds, mapfun, reducefun);
readall(outds)
function reduceMean(key, iter, kv)
    s = 0; n = 0;
    while hasnext(iter)
        v = getnext(iter); s = s + v(1); n = n + v(2);
    end
    add(kv, key, s/n);
end
